"""Lexer and recursive-descent parser for minisql. See SPEC.md, "Syntax".

``parse(sql)`` turns a query string into a ``nodes.Select`` tree, raising
``QueryError`` for any syntax error.

Notes on choices not pinned down by the spec:

* Comparisons don't chain: ``a = b = c`` (or ``a IS NULL = TRUE``) is a
  syntax error. Parenthesize to compare the result of a comparison.
* ``NOT`` sits below comparisons, so ``a = NOT b`` is a syntax error
  (write ``a = (NOT b)``); ``NOT NOT x`` is fine.
* ``name(*)`` is accepted for any function name (``star=True``); the
  executor rejects it for anything but ``COUNT``.
* SQL comments are not supported (``--`` is two minus signs).
* A number immediately followed by a letter, digit, underscore or ``.``
  (``1e5``, ``1.2.3``, ``12abc``) is a syntax error rather than being
  split into separate tokens.
"""

from . import nodes
from .errors import QueryError

KEYWORDS = frozenset(
    """
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
    """.split()
)

COMPARISON_OPS = ("=", "!=", "<>", "<", "<=", ">", ">=")

# Longest first, so that "<=" wins over "<".
OPERATORS = ("<=", ">=", "<>", "!=", "||", "=", "<", ">", "+", "-", "*", "/",
             "(", ")", ",", ";")

# Token kinds
KW = "keyword"
NAME = "name"      # unquoted identifier
QNAME = "qname"    # double-quoted identifier
INT = "integer"
FLOAT = "decimal"
STR = "string"
OP = "operator"
EOF = "end of input"


class Token:
    __slots__ = ("kind", "value", "start", "end")

    def __init__(self, kind, value, start, end):
        self.kind = kind
        self.value = value
        self.start = start
        self.end = end

    def __repr__(self):
        return "Token(%s, %r, %d, %d)" % (self.kind, self.value, self.start, self.end)


def _is_ident_start(c):
    return c == "_" or ("a" <= c <= "z") or ("A" <= c <= "Z")


def _is_ident_char(c):
    return _is_ident_start(c) or ("0" <= c <= "9")


def _is_digit(c):
    return "0" <= c <= "9"


def tokenize(sql):
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        start = i
        if _is_ident_start(c):
            while i < n and _is_ident_char(sql[i]):
                i += 1
            word = sql[start:i]
            upper = word.upper()
            if upper in KEYWORDS:
                tokens.append(Token(KW, upper, start, i))
            else:
                tokens.append(Token(NAME, word, start, i))
        elif _is_digit(c) or (c == "." and i + 1 < n and _is_digit(sql[i + 1])):
            while i < n and _is_digit(sql[i]):
                i += 1
            is_float = False
            if i < n and sql[i] == ".":
                is_float = True
                i += 1
                while i < n and _is_digit(sql[i]):
                    i += 1
            if i < n and (_is_ident_char(sql[i]) or sql[i] == "."):
                raise QueryError(
                    "syntax error: malformed number %r at position %d"
                    % (sql[start:i + 1], start)
                )
            text = sql[start:i]
            if is_float:
                tokens.append(Token(FLOAT, float(text), start, i))
            else:
                tokens.append(Token(INT, int(text), start, i))
        elif c == "'" or c == '"':
            quote = c
            i += 1
            parts = []
            while True:
                j = sql.find(quote, i)
                if j < 0:
                    what = "string" if quote == "'" else "quoted name"
                    raise QueryError(
                        "syntax error: unterminated %s starting at position %d"
                        % (what, start)
                    )
                parts.append(sql[i:j])
                if j + 1 < n and sql[j + 1] == quote:
                    parts.append(quote)
                    i = j + 2
                else:
                    i = j + 1
                    break
            value = "".join(parts)
            if quote == "'":
                tokens.append(Token(STR, value, start, i))
            else:
                if value == "":
                    raise QueryError(
                        "syntax error: empty quoted name at position %d" % start
                    )
                tokens.append(Token(QNAME, value, start, i))
        else:
            for op in OPERATORS:
                if sql.startswith(op, i):
                    i += len(op)
                    tokens.append(Token(OP, op, start, i))
                    break
            else:
                raise QueryError(
                    "syntax error: unexpected character %r at position %d" % (c, start)
                )
    tokens.append(Token(EOF, None, n, n))
    return tokens


class Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0
        self.prev_end = 0

    # ----- token helpers -------------------------------------------------

    @property
    def tok(self):
        return self.tokens[self.pos]

    def peek(self, offset=1):
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def advance(self):
        t = self.tokens[self.pos]
        if t.kind != EOF:
            self.pos += 1
        self.prev_end = t.end
        return t

    def is_kw(self, *words, tok=None):
        t = self.tok if tok is None else tok
        return t.kind == KW and t.value in words

    def is_op(self, *ops, tok=None):
        t = self.tok if tok is None else tok
        return t.kind == OP and t.value in ops

    def accept_kw(self, word):
        if self.is_kw(word):
            return self.advance()
        return None

    def accept_op(self, op):
        if self.is_op(op):
            return self.advance()
        return None

    def describe(self, t):
        if t.kind == EOF:
            return "end of input"
        return "%r at position %d" % (self.sql[t.start:t.end], t.start)

    def error(self, expected, t=None):
        t = self.tok if t is None else t
        return QueryError("syntax error: expected %s, found %s" % (expected, self.describe(t)))

    def expect_kw(self, word):
        if not self.is_kw(word):
            raise self.error(word)
        return self.advance()

    def expect_op(self, op):
        if not self.is_op(op):
            raise self.error("'%s'" % op)
        return self.advance()

    def expect_name(self, what="a name"):
        t = self.tok
        if t.kind in (NAME, QNAME):
            self.advance()
            return t.value
        if t.kind == KW:
            raise QueryError(
                "syntax error: expected %s, found keyword %s at position %d "
                "(keywords must be double-quoted to be used as names)"
                % (what, t.value, t.start)
            )
        raise self.error(what)

    def text_from(self, start):
        return self.sql[start:self.prev_end]

    # ----- query ---------------------------------------------------------

    def parse_query(self):
        if self.tok.kind == EOF:
            raise QueryError("syntax error: empty query")
        self.expect_kw("SELECT")
        distinct = bool(self.accept_kw("DISTINCT"))

        if self.is_op("*"):
            self.advance()
            columns = None
        else:
            columns = [self.parse_select_item()]
            while self.accept_op(","):
                columns.append(self.parse_select_item())
        if self.is_op(","):
            raise self.error("FROM")  # e.g. "SELECT *, a"

        self.expect_kw("FROM")
        table = self.expect_name("a table name")

        where = None
        if self.accept_kw("WHERE"):
            where = self.parse_expr()

        group_by = []
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group_by.append(self.parse_expr())
            while self.accept_op(","):
                group_by.append(self.parse_expr())

        having = None
        if self.accept_kw("HAVING"):
            having = self.parse_expr()

        order_by = []
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            order_by.append(self.parse_order_item())
            while self.accept_op(","):
                order_by.append(self.parse_order_item())

        limit = offset = None
        if self.accept_kw("LIMIT"):
            limit = self.parse_count("LIMIT")
            if self.accept_kw("OFFSET"):
                offset = self.parse_count("OFFSET")

        self.accept_op(";")
        if self.tok.kind != EOF:
            raise self.error("end of query")

        return nodes.Select(
            distinct=distinct,
            columns=columns,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def parse_select_item(self):
        if self.is_op("*"):
            raise QueryError(
                "syntax error: '*' at position %d must be the only item in the "
                "column list" % self.tok.start
            )
        expr = self.parse_expr()
        alias = None
        if self.accept_kw("AS"):
            alias = self.expect_name("a column alias after AS")
        elif self.tok.kind in (NAME, QNAME):
            alias = self.advance().value
        return nodes.SelectItem(expr, alias)

    def parse_order_item(self):
        expr = self.parse_expr()
        desc = False
        if self.accept_kw("DESC"):
            desc = True
        else:
            self.accept_kw("ASC")
        return nodes.OrderItem(expr, desc)

    def parse_count(self, clause):
        t = self.tok
        if t.kind != INT:
            raise self.error("a non-negative integer after %s" % clause)
        self.advance()
        return t.value

    # ----- expressions ---------------------------------------------------

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        start = self.tok.start
        left = self.parse_and()
        while self.accept_kw("OR"):
            right = self.parse_and()
            left = nodes.Binary("OR", left, right, text=self.text_from(start))
        return left

    def parse_and(self):
        start = self.tok.start
        left = self.parse_not()
        while self.accept_kw("AND"):
            right = self.parse_not()
            left = nodes.Binary("AND", left, right, text=self.text_from(start))
        return left

    def parse_not(self):
        start = self.tok.start
        if self.accept_kw("NOT"):
            operand = self.parse_not()
            return nodes.Unary("NOT", operand, text=self.text_from(start))
        return self.parse_comparison()

    def _at_comparison(self):
        t = self.tok
        if t.kind == OP and t.value in COMPARISON_OPS:
            return True
        if self.is_kw("IS", "IN", "BETWEEN", "LIKE"):
            return True
        if self.is_kw("NOT") and self.is_kw("IN", "BETWEEN", "LIKE", tok=self.peek()):
            return True
        return False

    def parse_comparison(self):
        start = self.tok.start
        left = self.parse_additive()
        if not self._at_comparison():
            return left

        t = self.tok
        if t.kind == OP:
            self.advance()
            right = self.parse_additive()
            node = nodes.Binary(t.value, left, right)
        elif self.accept_kw("IS"):
            negated = bool(self.accept_kw("NOT"))
            if not self.accept_kw("NULL"):
                raise self.error("NULL after IS NOT" if negated else "NULL or NOT NULL after IS")
            node = nodes.IsNull(left, negated)
        else:
            negated = bool(self.accept_kw("NOT"))
            if self.accept_kw("IN"):
                self.expect_op("(")
                if self.is_op(")"):
                    raise self.error("at least one expression in IN list")
                items = [self.parse_expr()]
                while self.accept_op(","):
                    items.append(self.parse_expr())
                self.expect_op(")")
                node = nodes.InList(left, items, negated)
            elif self.accept_kw("BETWEEN"):
                low = self.parse_additive()
                self.expect_kw("AND")
                high = self.parse_additive()
                node = nodes.Between(left, low, high, negated)
            else:
                self.expect_kw("LIKE")
                pattern = self.parse_additive()
                node = nodes.Like(left, pattern, negated)
        node.text = self.text_from(start)

        if self._at_comparison():
            raise QueryError(
                "syntax error: comparisons can't be chained (at %s); use "
                "parentheses" % self.describe(self.tok)
            )
        return node

    def parse_additive(self):
        start = self.tok.start
        left = self.parse_multiplicative()
        while self.is_op("+", "-", "||"):
            op = self.advance().value
            right = self.parse_multiplicative()
            left = nodes.Binary(op, left, right, text=self.text_from(start))
        return left

    def parse_multiplicative(self):
        start = self.tok.start
        left = self.parse_unary()
        while self.is_op("*", "/"):
            op = self.advance().value
            right = self.parse_unary()
            left = nodes.Binary(op, left, right, text=self.text_from(start))
        return left

    def parse_unary(self):
        start = self.tok.start
        if self.accept_op("-"):
            operand = self.parse_unary()
            return nodes.Unary("-", operand, text=self.text_from(start))
        return self.parse_primary()

    def parse_primary(self):
        t = self.tok
        start = t.start

        if t.kind in (INT, FLOAT, STR):
            self.advance()
            return nodes.Literal(t.value, text=self.text_from(start))
        if t.kind == KW:
            if t.value in ("NULL", "TRUE", "FALSE"):
                self.advance()
                value = {"NULL": None, "TRUE": True, "FALSE": False}[t.value]
                return nodes.Literal(value, text=self.text_from(start))
            raise QueryError(
                "syntax error: expected an expression, found keyword %s at "
                "position %d" % (t.value, t.start)
            )
        if t.kind == NAME and self.is_op("(", tok=self.peek()):
            self.advance()
            self.advance()  # "("
            name = t.value.upper()
            if self.is_op("*"):
                self.advance()
                self.expect_op(")")
                return nodes.FuncCall(name, [], star=True, text=self.text_from(start))
            args = []
            if not self.is_op(")"):
                args.append(self.parse_expr())
                while self.accept_op(","):
                    args.append(self.parse_expr())
            self.expect_op(")")
            return nodes.FuncCall(name, args, text=self.text_from(start))
        if t.kind in (NAME, QNAME):
            self.advance()
            return nodes.Column(t.value, text=self.text_from(start))
        if self.accept_op("("):
            inner = self.parse_expr()
            self.expect_op(")")
            inner.text = self.text_from(start)
            return inner
        raise self.error("an expression")


def parse(sql):
    """Parse a minisql query string into a ``nodes.Select``."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    return Parser(sql).parse_query()
